// strace - probe demo (function interposition model)
var calls = [];
function probe(name, fn) {
  return function() {
    var t0 = Date.now();
    var r = fn.apply(null, arguments);
    calls.push({ name: name, ms: Date.now() - t0 });
    return r;
  };
}
var work = probe("work", function(n) { var s = 0; for (var i = 0; i < n; i++) s += i; return s; });
console.log("Tool model: strace | Observes: syscalls");
console.log("work(100000) = " + work(100000));
console.log("Probe record: " + JSON.stringify(calls[0]));

